#include <iostream>
#include <string>
struct MyData {
  std::string data;
  MyData(const std::string& d) : data(d) { std::cout << "MyData constructor called\n"; }
  MyData(const MyData& other) : data(other.data) { std::cout << "MyData copy constructor called\n"; }
  ~MyData() { std::cout << "MyData destructor called\n"; }
};
MyData createData() {
  MyData d("Hello");
  return d;
}
int main() {
  MyData myData = createData();
  std::cout << myData.data << "\n";
  return 0;
}
